CREATE TABLE "accounts" ("updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, "id" TEXT NOT NULL, "name" TEXT NOT NULL, "type" TEXT NOT NULL, "bank_name" TEXT NULL, "last4" TEXT NULL, "sms_key" TEXT NULL, "balance_minor" INTEGER NOT NULL DEFAULT 0, "balance_as_of" INTEGER NULL, "include_in_total" INTEGER NOT NULL DEFAULT 1 CHECK ("include_in_total" IN (0, 1)), "color" INTEGER NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "budgets" ("updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, "id" TEXT NOT NULL, "category_id" TEXT NULL, "period" TEXT NOT NULL DEFAULT 'monthly', "amount_minor" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "categories" ("updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, "id" TEXT NOT NULL, "seed_key" TEXT NULL, "name" TEXT NOT NULL, "icon" TEXT NOT NULL, "color" INTEGER NOT NULL, "kind" TEXT NOT NULL, "parent_id" TEXT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "units" TEXT NOT NULL DEFAULT '', PRIMARY KEY ("id"));
CREATE TABLE "entries" ("updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, "id" TEXT NOT NULL, "kind" TEXT NOT NULL, "amount_minor" INTEGER NOT NULL, "currency" TEXT NOT NULL DEFAULT 'INR', "occurred_at" INTEGER NOT NULL, "category_id" TEXT NULL, "account_id" TEXT NULL, "to_account_id" TEXT NULL, "note" TEXT NOT NULL DEFAULT '', "payee" TEXT NULL, "source" TEXT NOT NULL DEFAULT 'manual', "sms_id" TEXT NULL, "group_id" TEXT NULL, "paid_by_member_id" TEXT NULL, "split_method" TEXT NULL, "tags" TEXT NOT NULL DEFAULT '', "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "entry_items" ("updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, "id" TEXT NOT NULL, "entry_id" TEXT NOT NULL, "name" TEXT NOT NULL, "quantity" REAL NOT NULL DEFAULT 1.0, "unit" TEXT NULL, "unit_price_minor" INTEGER NOT NULL, "amount_minor" INTEGER NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE TABLE "groups" ("updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, "id" TEXT NOT NULL, "name" TEXT NOT NULL, "icon" TEXT NOT NULL DEFAULT 'group', "currency" TEXT NOT NULL DEFAULT 'INR', "simplify_debts" INTEGER NOT NULL DEFAULT 1 CHECK ("simplify_debts" IN (0, 1)), "invite_code" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "members" ("updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, "id" TEXT NOT NULL, "group_id" TEXT NOT NULL, "name" TEXT NOT NULL, "phone" TEXT NULL, "email" TEXT NULL, "is_me" INTEGER NOT NULL DEFAULT 0 CHECK ("is_me" IN (0, 1)), "weight" REAL NOT NULL DEFAULT 1.0, PRIMARY KEY ("id"));
CREATE TABLE "settlements" ("updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, "id" TEXT NOT NULL, "group_id" TEXT NOT NULL, "from_member_id" TEXT NOT NULL, "to_member_id" TEXT NOT NULL, "amount_minor" INTEGER NOT NULL, "occurred_at" INTEGER NOT NULL, "note" TEXT NOT NULL DEFAULT '', PRIMARY KEY ("id"));
CREATE TABLE "sms_log" ("id" TEXT NOT NULL, "sender" TEXT NOT NULL, "body" TEXT NOT NULL, "received_at" INTEGER NOT NULL, "status" TEXT NOT NULL, "parsed_json" TEXT NULL, "entry_id" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "splits" ("updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted_at" INTEGER NULL, "id" TEXT NOT NULL, "entry_id" TEXT NOT NULL, "member_id" TEXT NOT NULL, "amount_minor" INTEGER NOT NULL, "share_value" REAL NULL, PRIMARY KEY ("id"));
